const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='checkride-connect-demo-v1';let state,baseline=null,initialLoadFailed=false;try{baseline=localStorage.getItem(STORAGE);state=migratePilot(migrateWorkflows(migrateState(JSON.parse(baseline))))}catch{state=migratePilot(migrateWorkflows(seed()));initialLoadFailed=true}
let role='student',page='dashboard',examinerId='elena',studentId='maya',filters=emptyFilters(),toastTimer,workspaceId=null,moreFiltersOpen=false,schoolFilters={query:'',view:'all'};const app=$('#app'),modal=$('#modal');
let saveFailed=initialLoadFailed,draftResetFailed=false,persistedDraftReceipts=state.draftReceipts||{};
const draftStore=createDraftStore(()=>localStorage);
const draftsFailed=()=>draftResetFailed||draftStore.failed;
function migratePilot(s){return migrateTemplates(s);}
function persistenceStatus(){let el=$('#save-state');if(!el){el=document.createElement('div');el.id='save-state';el.setAttribute('role','status');el.setAttribute('aria-live','polite');app.before(el);}el.className='save-state '+(saveFailed||draftsFailed()?'save-error':'');el.innerHTML=saveFailed||draftsFailed()?'Not saved to this browser. Keep this tab open and retry before leaving. <button class="btn small" data-action="retry-save">Retry saving</button>':(baseline?'Saved in this browser only':'Changes save in this browser only');}
function save(){try{state.draftReceipts={...(state.draftReceipts||{}),...draftStore.submissionReceipts};const next=JSON.stringify(state);localStorage.setItem(STORAGE,next);baseline=next;saveFailed=false;persistedDraftReceipts=state.draftReceipts;commitSavedDrafts()}catch{saveFailed=true}persistenceStatus();return !saveFailed}
function toast(text){$('#toast').textContent=saveFailed||draftsFailed()?'Changes are in this session only. Browser saving failed. Use Retry saving.':text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
const actor=()=>({role,id:role==='student'?studentId:examinerId});
function money(n){return '$'+Number(n).toLocaleString('en-US')}function date(d){return new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}function longDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}function time(t){const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`}const airportNames={KJQF:'Concord–Padgett',KRUQ:'Mid-Carolina Regional',KEQY:'Charlotte–Monroe',KUZA:'Rock Hill'};const eBy=id=>state.examiners.find(e=>e.id===id),sBy=id=>state.students.find(s=>s.id===id);const available=e=>e.slots.filter(s=>!state.requests.some(r=>r.examinerId===e.id&&r.date===s.date&&r.status==='accepted'));const statusLabel={pending:'Awaiting DPE',accepted:'Confirmed',declined:'Declined',cancelled:'Cancelled'};
const iconPaths={find:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',requests:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 9h6M9 13h6M9 17h4"/>',availability:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 10h18M7 14h2M15 14h2M7 17h2"/>',school:'<path d="M3 21V7l9-4 9 4v14M8 21v-5h8v5M7 9h2M15 9h2M7 12h2M15 12h2"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.requests}</svg>`}
function status(r){return `<span class="status ${r.status}">${r.status==='pending'?(r.pendingOffer?.status==='pending'?'Alternate opening offered':!pendingRequestAvailability(state,r).available?'Pending · opening unavailable':pendingClarification(r)?'Clarification requested':!r.agreement?.studentAcknowledgedAt?'Student review needed':statusLabel.pending):statusLabel[r.status]}</span>`}function options(values,selected=''){return values.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function intro(eyebrow,title,subtitle,extra=''){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${extra}</div>`}
function roleSelector(kind){const isE=kind==='examiner';return `<div class="field workspace-select"><label for="active-person">${isE?'Preview examiner':'Preview student'}</label><select id="active-person">${(isE?state.examiners:state.students).map(p=>`<option value="${p.id}" ${p.id===(isE?examinerId:studentId)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`}
function render({navigation=false}={}){const key=focusKey(document.activeElement)||modalOpener;const drafts=captureForms(app);const nav=role==='student'?[['find','⌕','Find an examiner'],['requests','▤','My checkrides']]:role==='examiner'?[['requests','▤','Checkride requests'],['availability','▦','Availability & fees']]:[['school','▦','Student overview'],['find','⌕','Find an examiner'],['requests','▤','School requests']];nav.unshift(['dashboard','◎','Action needed']);$('#nav').innerHTML=nav.map(([id,icon,name])=>`<button class="nav-item ${id===page?'active':''}" data-page="${id}" ${id===page?'aria-current="page"':''}><span class="nav-icon">${iconPaths[id]?`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[id]}</svg>`:icon}</span>${name}</button>`).join('');$('#role').value=role;const person=role==='examiner'?eBy(examinerId):role==='student'?sBy(studentId):{name:'Piedmont Flight Academy',initials:'PF'};$('#profile').innerHTML=`<div class="avatar">${person.initials}</div><div><b>${esc(person.name)}</b><small>${role==='school'?'Sample flight school':'Demo account'}</small></div>`;$('#breadcrumb').textContent=`${role==='examiner'?'Examiner':role==='school'?'Flight school':'Student'} workspace / ${(page==='workspace'?'Checkride workspace':nav.find(n=>n[0]===page)?.[2])||''}`;app.innerHTML=page==='dashboard'?dashboardPage():page==='workspace'?workspacePage():page==='find'?findPage():page==='availability'?availabilityPage():page==='school'?schoolPage():requestsPage();restoreDurableDrafts(app);if(!navigation)restoreForms(app,drafts,submittedForm);submittedForm=null;persistenceStatus();if(navigation)syncRoute();const heading=app.querySelector('h1');if(heading)heading.tabIndex=-1;if(navigation)heading?.focus();else restoreFocus(key);if(!modal.open)modalOpener=null;}
function findPage(){const list=discoverExaminers(state,filters,airportNames);return intro('YOUR NEXT MILESTONE','Find your examiner.','Find the right examiner. Know the details. Take your next step with confidence.',role==='student'?roleSelector('student'):'')+`<section class="hero"><div><p class="eyebrow">LESS BACK AND FORTH. MORE FORWARD.</p><h2>Your checkride starts<br>with a better connection.</h2><p>Explore sample availability, transparent fees, and examiner preferences, all in one place.</p></div><div class="sky-art" aria-hidden="true"><svg viewBox="0 0 400 190" fill="none"><path d="M0 121 45 98 81 109 141 63 189 96 231 73 284 99 337 70 400 104V190H0Z" fill="#D6E9FC"/><path d="M0 143 55 116 106 131 169 106 221 127 278 104 331 132 400 112V190H0Z" fill="#C6E0FB"/><path data-flight-trail d="M44 92C100 30 170 52 240 52" stroke="#2563EB" stroke-width="2" stroke-dasharray="4 6"/><g data-flight-aircraft transform="translate(270 52) rotate(90) translate(-26 -25)"><path d="M24 4c0-3 4-3 4 0v15l17 13v5l-17-7v12l5 4v3l-7-2-7 2v-3l5-4V30L7 37v-5l17-13V4Z" fill="#2563EB"/></g></svg></div></section><form id="filters" class="filters discovery-filters" aria-describedby="discovery-context"><div class="field discovery-search"><label for="query-filter">SEARCH NAME, AIRPORT OR CITY</label><input type="search" id="query-filter" maxlength="120" placeholder="e.g. Elena, KJQF or Concord" value="${esc(filters.query)}"></div><div class="field"><label for="certificate-filter">CERTIFICATE OR RATING</label><select id="certificate-filter"><option value="">All certificates & ratings</option>${options(['Private pilot','Instrument rating','Commercial pilot'],filters.certificate)}</select></div><div class="field"><label for="airport-filter">PREFERRED AIRPORT</label><select id="airport-filter"><option value="">All sample airports</option>${Object.entries(airportNames).map(([code,name])=>`<option value="${code}" ${filters.airport===code?'selected':''}>${code} · ${name}</option>`).join('')}</select></div><details id="more-filters" class="discovery-more" ${moreFiltersOpen?'open':''}><summary>More filters${filters.start||filters.end||filters.maxFee!==''?' · Active':''}</summary><div class="discovery-extra"><div class="field"><label for="start-filter">ON OR AFTER · EASTERN DATE</label><input type="date" id="start-filter" value="${esc(filters.start)}"></div><div class="field"><label for="end-filter">ON OR BEFORE · EASTERN DATE</label><input type="date" id="end-filter" value="${esc(filters.end)}"></div><div class="field"><label for="fee-filter">MAX SAMPLE INITIAL FEE ($)</label><input type="number" id="fee-filter" min="0" step="1" placeholder="No maximum" value="${esc(filters.maxFee)}"></div></div></details><div class="discovery-controls"><div class="field"><label for="sort-filter">SORT BY</label><select id="sort-filter">${[['earliest','Earliest opening'],['fee','Lowest initial fee'],['name','Examiner name']].map(([value,label])=>`<option value="${value}" ${filters.sort===value?'selected':''}>${label}</option>`).join('')}</select></div><button class="filter-button" type="submit">Find examiners →</button><button class="btn" type="button" data-action="clear-filters">Reset filters</button></div><p id="discovery-context" class="location discovery-context">All times Eastern. Fees are sample initial fees.</p><p id="filter-error" class="error" role="alert"></p></form><div class="section-row"><h2 id="discovery-results" role="status" aria-live="polite" aria-atomic="true">${list.length} sample examiner${list.length===1?'':'s'} · ${list.reduce((n,row)=>n+row.slots.length,0)} matching openings</h2><small>Illustrative availability · Eastern time</small></div><div class="cards">${list.map(examinerCard).join('')}</div>${!list.length?'<div class="panel empty"><span class="empty-icon">⌕</span><strong>No matching examiners</strong>Try a wider date window, higher sample fee limit, or another airport.<div class="actions" style="justify-content:center"><button class="btn" data-action="clear-filters">Reset filters</button></div></div>':''}<div class="callout"><span class="symbol">◎</span><div><b>You request. Your examiner confirms.</b>A request doesn’t hold the slot until your examiner accepts it.</div></div>`}
function examinerCard({examiner:e,slots}){return `<article class="examiner-card"><div class="card-identity"><div class="portrait ${e.id}" aria-hidden="true">${e.initials}</div><div><div class="name-row"><h3>${esc(e.name)}</h3><span class="demo-chip">Demo</span></div><p class="location">${esc(e.location)} · Fictional examiner</p><p class="quote">${esc(e.bio)}</p></div></div><div class="card-details"><div class="tags">${e.certificates.map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div><div class="airport-line"><span class="meta-label">Preferred airports</span><b>${e.airports.join(' · ')}</b></div></div><div class="card-booking"><div class="fee">${money(e.fee)}<small>Sample initial fee</small></div><div class="availability">${slots.length?'Next: '+date(slots[0].date)+' · '+time(slots[0].time)+' ET':'No matching openings'}<span>${esc(availabilityFreshness(e).label)}</span><span>${slots.length} sample opening${slots.length!==1?'s':''}</span></div><button class="btn primary" data-action="view-examiner" data-id="${e.id}">View & request <span aria-hidden="true">→</span></button></div></article>`}
function requestsForRole(){return state.requests.filter(r=>role==='student'?r.studentId===studentId:role==='examiner'?r.examinerId===examinerId:canSchool(state,r.studentId))}
function requestsPage(){const rs=requestsForRole(),pending=rs.filter(r=>r.status==='pending').length,accepted=rs.filter(r=>r.status==='accepted').length;return intro(role==='examiner'?'YOUR EXAMINER DESK':'YOUR CHECKRIDE JOURNEY',role==='examiner'?'More clarity. Less admin.':role==='school'?'Every request, in one place.':'One step closer to takeoff.',role==='examiner'?'Review requests, confirm a match, and set students up with a clear preparation checklist.':'Follow each request from first connection through your checkride preparation.',role==='school'?'':roleSelector(role))+`<div class="stats"><div class="stat"><label>PENDING REQUESTS</label><b>${pending}</b><small>Requests, not bookings</small></div><div class="stat"><label>CONFIRMED</label><b>${accepted}</b><small>Accepted by examiner</small></div><div class="stat"><label>TOTAL REQUESTS</label><b>${rs.length}</b><small>Including history</small></div></div><section class="panel"><div class="panel-head"><h2>${role==='examiner'?'Your checkride requests':'Request activity'}</h2></div>${rs.length?rs.slice().reverse().map(requestCard).join(''):`<div class="empty"><span class="empty-icon">→</span><strong>${role==='examiner'?'Your inbox is clear':'Your next milestone is waiting'}</strong>${role==='examiner'?'Switch to Student and send a request to this examiner to try the flow.':'Browse examiners and send a request to get started.'}${role!=='examiner'?'<div class="actions" style="justify-content:center"><button class="btn primary" data-page="find">Find an examiner →</button></div>':''}</div>`}</section>`}
function requestCard(r){const e=eBy(r.examinerId),s=sBy(r.studentId),done=r.checklist.filter(c=>c.done).length;return `<article class="request"><div class="date-tile"><span>${date(r.date).split(' ')[0].toUpperCase()}</span><b>${date(r.date).split(' ')[1]}</b></div><div class="request-body"><h3>${esc(role==='student'?e.name:s.name)} · ${esc(r.certificate)}</h3><p>${r.airport} · ${time(r.time)} Eastern · ${money(r.fee)} sample fee<br>${role==='school'?esc(e.name)+' · ':''}${r.source==='Flight school'?'Requested by flight school':'Student request'}${r.status==='pending'?' · Not yet reserved':''}</p>${requestNextStepMarkup(r)}${r.status==='accepted'?`<div class="location">${r.coordination&&r.coordination!=='scheduled'?'User-reported '+esc(r.coordination)+' · ':''}${r.rescheduleProposal?'Schedule change awaiting response · ':''}Preparation: ${done} of ${r.checklist.length} items complete</div><div class="progress-track"><span style="width:${r.checklist.length?done/r.checklist.length*100:0}%"></span></div>`:''}<div class="actions"><button class="btn small" data-action="workspace" data-id="${r.id}">${r.status==='accepted'?'Open checkride workspace':'View request details'}</button>${role==='examiner'&&r.status==='pending'&&!r.pendingOffer&&!pendingRequestAvailability(state,r).available?`<button class="btn small" data-action="offer-opening" data-id="${r.id}">Offer another opening</button>`:''}${role==='examiner'&&r.status==='pending'?`<button class="btn primary small" data-action="review" data-id="${r.id}">Review & accept</button><button class="btn small" data-action="decline" data-id="${r.id}">Decline</button>`:''}${r.status==='accepted'?`<button class="btn small" data-action="checklist" data-id="${r.id}">${role==='examiner'?'Curate checklist':'View checklist'} →</button>`:''}${((role==='student'&&['pending','accepted'].includes(r.status))||(role==='examiner'&&r.status==='accepted'))?`<button class="btn small danger" data-action="cancel" data-id="${r.id}">${r.status==='pending'?'Withdraw request':'Cancel checkride'}</button>`:''}</div></div>${status(r)}</article>`}
const calendars=new Map();
function calendarState(e){if(!calendars.has(e.id)){const selected=initialCalendarDate(e,state.requests);calendars.set(e.id,{view:'month',month:selected.slice(0,7),selected})}return calendars.get(e.id)}
function availabilityRows(e,slots){return slots.map(s=>{
 const summary=summarizeDay(e,state.requests,s.date),slot=summary.slots.find(x=>x.id===s.id);
 const label=slot.confirmed?'Confirmed':slot.blocked?'Unavailable · another checkride confirmed this day':slot.pending?`${slot.pending} pending request${slot.pending===1?'':'s'} · Not reserved`:'Open · No pending requests';
 return `<div class="slot-row"><div><strong>${longDate(s.date)} · ${time(s.time)}</strong><small>${esc(s.airport)} · Eastern time · ${label}</small></div><button class="btn small" data-action="remove-slot" data-id="${esc(s.id)}" ${!slot.removable?'disabled title="Resolve active requests or the confirmed day first"':''}>Remove</button></div>`;
 }).join('')}
function calendarPanel(e){const c=calendarState(e),day=summarizeDay(e,state.requests,c.selected);
 return `<div class="calendar-toolbar"><button class="btn" data-action="calendar-prev" aria-label="Previous month" ${c.month==='0001-01'?'disabled':''}>←</button><h3 id="calendar-month" aria-live="polite">${monthLabel(c.month)}</h3><button class="btn" data-action="calendar-next" aria-label="Next month" ${c.month==='9999-12'?'disabled':''}>→</button></div>
 <p class="location calendar-key">One confirmed checkride closes the day.</p>
 ${!e.slots.some(s=>s.date.startsWith(c.month))?'<p class="notice">No published openings this month. Browse another month or add an opening.</p>':''}<div class="calendar-scroll"><div class="calendar-weekdays" aria-hidden="true">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days" role="group" aria-labelledby="calendar-month">${monthCells(c.month).map(d=>{if(!d)return '<span class="calendar-blank" aria-hidden="true"></span>';const x=summarizeDay(e,state.requests,d),labels=[`${x.openings} open`,...(x.pending.length?[`${x.pending.length} pending`]:[]),...(x.confirmed.length?[`${x.confirmed.length} confirmed`]:[]),...(x.proposals.length?[`${x.proposals.length} proposed`]:[])];return `<button class="calendar-day ${x.confirmed.length?'has-confirmed':''}" data-action="calendar-day" data-id="${d}" aria-pressed="${d===c.selected}" aria-label="${d}, ${labels.join(', ')}"><b>${Number(d.slice(-2))}</b>${labels.map(label=>`<span>${label}</span>`).join('')}</button>`}).join('')}</div></div>
 <section class="calendar-detail" aria-labelledby="calendar-selected"><h3 id="calendar-selected" aria-live="polite">${longDate(c.selected)}, ${c.selected.slice(0,4)}</h3>${day.slots.length?availabilityRows(e,day.slots):'<p class="subtitle">No published openings on this day. Use Add opening to offer a sample time.</p>'}${day.confirmed.length?`<p class="location">${day.confirmed.length} confirmed checkride · Other openings on this day are unavailable.</p>`:''}${day.pending.length?`<p class="location">${day.pending.length} pending request${day.pending.length===1?'':'s'} · Not reservations.</p>`:''}${day.proposals.length?`<p class="notice">${day.proposals.length} proposed schedule change${day.proposals.length===1?'':'s'} to this day. Not confirmed; the original appointment remains confirmed until acceptance.</p>`:''}${day.confirmed.length||day.pending.length||day.proposals.length?'<button class="btn" data-page="requests">Review checkride requests →</button>':''}</section>`;
}
function availabilityPage(){const e=eBy(examinerId),c=calendarState(e);return intro('YOUR SCHEDULE, YOUR CONTROL','Make room for what’s next.','Publish openings and keep your fees clear.',roleSelector('examiner'))+`<div class="grid-two availability-layout"><section class="panel availability-panel"><div class="panel-head"><h2>Your published openings</h2><button class="btn primary small" data-action="add-slot">+ Add opening</button></div><div class="calendar-view" role="group" aria-label="Availability display">${['month','list'].map(view=>`<button class="btn" data-action="calendar-view" data-id="${view}" aria-pressed="${c.view===view}">${view==='month'?'Month':'List'}</button>`).join('')}</div><p class="location">All times Eastern</p>${c.view==='month'?calendarPanel(e):e.slots.length?availabilityRows(e,e.slots.slice().sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))):'<p class="subtitle">No openings yet. Add one to appear in student searches.</p>'}<p class="location" style="margin-top:18px">${esc(availabilityFreshness(e).label)}</p><button class="btn" data-action="reconfirm">Reconfirm current availability</button></section><section class="panel"><div class="panel-head"><h2>Fees & preferences</h2></div><form id="fees"><div class="form-grid"><div class="field"><label for="initial-fee">Sample initial fee (USD)</label><input id="initial-fee" type="number" min="0" max="10000" step="1" required value="${e.fee}"></div><div class="field"><label for="retest-fee">Sample retest fee (USD)</label><input id="retest-fee" type="number" min="0" max="10000" step="1" required value="${e.retestFee}"></div></div><div class="field" style="margin-top:17px"><label for="preferences">Scheduling preferences</label><textarea id="preferences" maxlength="500" required>${esc(e.notice)}</textarea></div><p class="location">Fee changes don’t affect requests already sent.</p>${termKeys.map(k=>`<div class="field"><label for="term-${k}">${k[0].toUpperCase()+k.slice(1)} terms</label><textarea id="term-${k}" maxlength="500" placeholder="Not disclosed — leave blank if unknown">${esc(e.terms?.[k]||'')}</textarea></div>`).join('')}<div class="form-actions"><button class="btn primary" type="submit">Save preferences</button></div></form></section></div>${templatesPanel(state,examinerId)}`}
function schoolPage(){
 const rows=schoolSummaries(state).filter(row=>canSchool(state,row.student.id)),shown=filterSchoolSummaries(rows,schoolFilters);
 return intro('PIEDMONT FLIGHT ACADEMY · SAMPLE SCHOOL','Keep your students moving.','Know who needs a match, who is waiting, and what is already confirmed.')+`
 <div class="stats"><div class="stat"><label>STUDENTS</label><b>${rows.length}</b><small>Fictional sample roster</small></div><div class="stat"><label>AWAITING EXAMINER</label><b>${rows.reduce((n,r)=>n+r.pending.length,0)}</b><small>Pending requests</small></div><div class="stat"><label>CONFIRMED</label><b>${rows.reduce((n,r)=>n+r.confirmed.length,0)}</b><small>Accepted by examiner</small></div></div>
 ${boardPanel(state)}<section class="panel school-focus"><div class="panel-head"><h2>Coordination focus</h2></div><div class="school-focus-grid">${schoolViews.slice(1).map(([view,label])=>`<button class="school-focus-item" data-action="school-filter" data-id="${view}" aria-pressed="${schoolFilters.view===view}"><b>${rows.filter(r=>matchesSchoolView(r,view)).length}</b><span>${label}</span></button>`).join('')}</div></section>
 <section class="panel"><div class="panel-head"><h2>Student coordination</h2></div><form id="school-filters" class="school-filters"><div class="field"><label for="school-query">SEARCH STUDENT NAME</label><input id="school-query" type="search" maxlength="120" value="${esc(schoolFilters.query)}" placeholder="e.g. Maya"></div><div class="field"><label for="school-view">COORDINATION STATUS</label><select id="school-view">${schoolViews.map(([value,label])=>`<option value="${value}" ${schoolFilters.view===value?'selected':''}>${label}</option>`).join('')}</select></div><button type="submit" class="btn primary">Apply filters</button><button type="button" class="btn" data-action="school-reset">Reset</button></form><p id="school-results" class="location" role="status">${shown.length} of ${rows.length} sample students · ${esc(schoolViews.find(([v])=>v===schoolFilters.view)?.[1]||'All students')}</p>
 ${shown.length?shown.map(schoolStudentCard).join(''):`<div class="empty"><strong>No students match these filters.</strong><p>Try another name or coordination status.</p><button class="btn" data-action="school-reset">Show all students</button></div>`}</section>
 <div class="callout"><span class="symbol">◇</span><div><b>One school. Every student. No feature gates.</b>Only students who have shared access with the school appear here.</div></div>`;
}
function schoolStudentCard(row){
 const {student:s,pending,confirmed,history}=row;
 return `<article class="school-student"><div class="school-student-head"><div class="avatar">${esc(s.initials)}</div><div class="student-info"><h3>${esc(s.name)}</h3><small>${esc(s.certificate)} · ${esc(s.airport)}</small></div><div class="school-badges">${confirmed.length?`<span class="status accepted">${confirmed.length} confirmed</span>`:''}${pending.length?`<span class="status pending">${pending.length} pending</span>`:''}${row.unassigned?'<span class="location">No active request</span>':''}</div></div>
 ${confirmed.map(({request:r,done,total,respondingRole})=>`<div class="school-arrangement"><div><b>Confirmed · ${longDate(r.date)} · ${time(r.time)} Eastern</b><p>${esc(eBy(r.examinerId).name)} · ${esc(r.certificate)} · ${esc(r.airport)}</p><p>User-reported coordination: ${esc(r.coordination||'scheduled')}</p><p>${total?`Preparation: ${done} of ${total} items complete`:'No checklist items yet'}</p>${total?`<div class="progress-track" aria-label="${done} of ${total} checklist items complete"><span style="width:${done/total*100}%"></span></div>`:''}${respondingRole?`<p class="school-proposal"><strong>Proposed change · Not confirmed</strong><br>${longDate(r.rescheduleProposal.to.date)} · ${time(r.rescheduleProposal.to.time)} Eastern · ${esc(r.rescheduleProposal.to.airport)}<br>Awaiting ${respondingRole} response. The original appointment above remains confirmed.</p>`:''}</div><button class="btn small" data-action="workspace" data-id="${r.id}">Open workspace →</button></div>`).join('')}
 ${pending.map(r=>`<div class="school-arrangement"><div><b>Awaiting examiner review · Not reserved</b><p>${esc(eBy(r.examinerId).name)} · ${longDate(r.date)} · ${time(r.time)} Eastern · ${esc(r.airport)} · ${esc(r.certificate)}</p></div><button class="btn small" data-action="workspace" data-id="${r.id}">View request →</button></div>`).join('')}
 <div class="school-student-footer"><button class="btn small ${row.unassigned?'primary':''}" data-action="school-find" data-id="${s.id}">${row.unassigned?'Find a match':'Find another match'} →</button>${history.length?`<details class="school-history"><summary>${history.length} historical ${history.length===1?'request':'requests'}</summary>${history.slice().reverse().map(r=>`<div class="school-history-row"><span>${statusLabel[r.status]} · ${esc(eBy(r.examinerId).name)} · ${longDate(r.date)}</span><button class="text-button" data-action="workspace" data-id="${r.id}">View details</button></div>`).join('')}</details>`:'<span class="location">No previous request history</span>'}</div></article>`;
}
function openModal(html){if(!modal.open)modalOpener=focusKey(document.activeElement);$('#modal-body').innerHTML=html;restoreDurableDrafts(modal);if(!modal.open)modal.showModal()}function modalHead(title){return `<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`}function modalError(error){let el=$('#modal-error');if(el)el.textContent=error.message||String(error);else toast(error.message||String(error))}
function examinerModal(id){if(role==='school'&&!state.students.some(s=>canSchool(state,s.id,'coordinate')))return toast('No student has granted request-coordination permission. Switch to a student’s Action needed page to try that scope.');if(role==='school'&&!canSchool(state,studentId,'coordinate'))studentId=state.students.find(s=>canSchool(state,s.id,'coordinate')).id;const e=eBy(id),slots=discoverExaminers(state,filters,airportNames).find(row=>row.examiner.id===id)?.slots||[];openModal(modalHead(esc(e.name))+`<div class="dialog-subtitle">Fictional examiner · ${esc(e.location)}<br>${esc(e.bio)}</div><div class="dialog-meta"><div>Sample initial fee<b>${money(e.fee)}</b></div><div>Sample retest fee<b>${money(e.retestFee)}</b></div><div>Preferred airports<b style="font-size:13px">${e.airports.join(' · ')}</b></div></div><p class="subtitle">${esc(e.notice)}</p><form id="request-form" data-examiner="${id}" data-student="${studentId}"><div class="form-grid" style="margin-top:20px">${role==='school'?`<div class="field"><label for="request-student">Student with request-coordination permission</label><select id="request-student">${state.students.filter(s=>canSchool(state,s.id,'coordinate')).map(s=>`<option value="${s.id}" ${s.id===studentId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label for="request-certificate">Certificate or rating</label><select id="request-certificate">${options(e.certificates,filters.certificate||sBy(studentId).certificate)}</select></div></div><div class="form-grid request-details"><div class="field"><label for="request-aircraft">Aircraft make and model</label><input id="request-aircraft" maxlength="80" required placeholder="e.g. Cessna 172S (sample)"></div><div class="field"><label for="request-readiness">Readiness</label><select id="request-readiness" required><option value="">Choose a status</option>${options(readinessOptions.filter(x=>x!=='Not provided'))}</select></div></div><div class="field request-details"><label for="request-notes">Notes for your examiner (optional)</label><textarea id="request-notes" maxlength="1000" placeholder="e.g. Questions about aircraft or location (please use fictional details)"></textarea></div><p class="dialog-section">Matching openings · All times Eastern</p>${slots.length?slots.map((s,i)=>`<label class="slot-option"><input type="radio" name="slot" value="${s.id}" required ${i===0?'checked':''}>${longDate(s.date)} · ${time(s.time)}<small>${s.airport}</small></label>`).join(''):'<div class="empty">No matching openings. Try a wider date window or another airport or examiner.</div>'}<p class="location">${esc(availabilityFreshness(e).label)}</p><div class="notice"><strong>A request is not a booking.</strong> Your examiner must accept it first. No money is collected.</div><div id="modal-error" class="error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close">Not now</button><button class="btn primary" type="submit" ${slots.length?'':'disabled'}>Send demo request →</button></div></form>`)}
function confirmModal(title,body,action,id,label){openModal(modalHead(title)+`<p class="dialog-subtitle">${body}</p><div id="modal-error" class="error" role="alert"></div><div class="form-actions"><button class="btn" data-action="close">Go back</button><button class="btn primary" data-action="${action}" data-id="${id||''}">${label}</button></div>`)}
function checklistModal(id){const r=state.requests.find(r=>r.id===id);if(!r||r.status!=='accepted')return toast('Checklists are available after acceptance.');openModal(modalHead(role==='examiner'?'Build a clear path to test day.':'Your checkride preparation.')+`<p class="dialog-subtitle">${esc(sBy(r.studentId).name)} · ${esc(r.certificate)}<br>${date(r.date)} · ${r.airport} · ${esc(eBy(r.examinerId).name)}</p><p class="location">A preparation aid, not an official FAA requirement list.</p>${role==='examiner'?`<form id="checklist-form" data-id="${id}"><div id="checklist-editor">${r.checklist.map(c=>`<div class="check-edit"><input aria-label="Checklist item" value="${esc(c.text)}" data-item="${esc(c.id)}" maxlength="250" required><select aria-label="Preparation group"><option value="before" ${c.group!=='bring'?'selected':''}>Before the test</option><option value="bring" ${c.group==='bring'?'selected':''}>Bring with you</option></select><button type="button" data-action="remove-item" aria-label="Remove checklist item">×</button></div>`).join('')}</div><button class="btn small" type="button" data-action="add-item">+ Add checklist item</button><div class="form-actions"><button class="btn primary" type="submit">Save checklist</button></div></form>`:`<ul class="checklist">${r.checklist.map(c=>`<li><label class="${c.done?'done':''}"><input type="checkbox" data-check-request="${id}" data-check-item="${c.id}" ${c.done?'checked':''} ${role==='school'?'disabled':''}>${esc(c.text)}</label></li>`).join('')}</ul>${!r.checklist.length?'<div class="empty">Your examiner has not added checklist items yet.</div>':''}<div class="form-actions"><button class="btn primary" data-action="close">Done</button></div>`}`)}
function slotModal(){const e=eBy(examinerId);openModal(modalHead('Publish a new opening')+`<p class="dialog-subtitle">Add an opening for ${esc(e.name)}.</p><form id="slot-form"><div class="form-grid"><div class="field"><label for="slot-date">Date</label><input type="date" id="slot-date" min="${new Date().toISOString().slice(0,10)}" required value="${calendarState(e).selected}"></div><div class="field"><label for="slot-time">Start time · Eastern</label><input type="time" id="slot-time" required value="09:00"></div><div class="field"><label for="slot-airport">Operating airport</label><select id="slot-airport">${options(e.airports)}</select></div></div><div id="modal-error" class="error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close">Cancel</button><button class="btn primary" type="submit">Publish opening</button></div></form>`)}

function appointmentText(a){return `${longDate(a.date)} · ${time(a.time)} Eastern · ${esc(a.airport)}`}
function schedulePanel(r){
 const p=r.rescheduleProposal,history=r.rescheduleHistory||[],assigned=(role==='student'&&r.studentId===studentId)||(role==='examiner'&&r.examinerId===examinerId);
 return `<section class="panel reschedule-panel"><div class="panel-head"><h2>Schedule changes</h2></div>${r.status==='accepted'?`<div class="schedule-current"><span class="meta-label">Still confirmed</span><strong>${appointmentText(r)}</strong></div>${p?`<div class="schedule-proposal"><span class="status pending">Proposed · Not confirmed</span><h3>${appointmentText(p.to)}</h3><p>Proposed by ${p.actorRole==='student'?'the student':'the examiner'}. The current time stays confirmed until the other person accepts.</p>${assigned?`<div class="actions">${p.actorRole===role?`<button class="btn" data-action="reschedule-withdrawn" data-id="${r.id}" data-proposal="${esc(p.id)}">Withdraw proposal</button>`:`<button class="btn primary" data-action="reschedule-review" data-id="${r.id}" data-proposal="${esc(p.id)}">Review proposed change</button><button class="btn" data-action="reschedule-declined" data-id="${r.id}" data-proposal="${esc(p.id)}">Decline change</button>`}</div>`:''}</div>`:assigned&&(!r.coordination||r.coordination==='scheduled')?`<p class="subtitle">Need another day? Suggest an opening with this examiner without losing your confirmed appointment.</p><button class="btn" data-action="reschedule" data-id="${r.id}">Propose a new time</button>`:assigned?'<p class="notice">Scheduling changes are paused after a post-test report. To correct an ongoing appointment, change coordination above to Scheduled / correction first. For a separate retest or continuation, create a new request.</p>':''}${role==='school'?'<p class="notice">School preview is read-only for schedule changes. The assigned student and examiner must agree.</p>':''}`:'<p class="subtitle">Schedule changes are available only for confirmed appointments.</p>'}${history.length?`<details class="schedule-history"><summary>Schedule history (${history.length})</summary><ol>${history.slice().reverse().map(h=>`<li><strong>${esc({pending:'Awaiting response',accepted:'Change accepted',declined:'Change declined',withdrawn:'Proposal withdrawn',cancelled:'Appointment cancelled'}[h.status]||h.status)}</strong><span>From: ${appointmentText(h.from)}</span><span>To: ${appointmentText(h.to)}</span><small>Proposed by ${esc(h.actorRole)} · ${esc(new Date(h.createdAt).toLocaleString('en-US',{timeZone:'America/New_York'}))} Eastern</small></li>`).join('')}</ol></details>`:''}</section>`;
}
function rescheduleModal(id){
 const r=state.requests.find(x=>x.id===id),slots=rescheduleOpenings(state,id);
 openModal(modalHead('Propose a new time')+`<p class="subtitle">Same examiner: ${esc(eBy(r.examinerId).name)}. Your original appointment remains confirmed until the other participant accepts.</p><div class="schedule-current"><span class="meta-label">Currently confirmed</span><strong>${appointmentText(r)}</strong></div><form id="reschedule-form" data-id="${r.id}" data-client="${crypto.randomUUID()}"><fieldset class="reschedule-choices"><legend>Choose a proposed opening · Eastern time</legend>${slots.length?slots.map((s,i)=>`<label class="slot-option"><input type="radio" name="reschedule-slot" value="${esc(s.id)}" required ${i===0?'checked':''}>${appointmentText(s)}</label>`).join(''):'<p class="notice">No other available openings match this appointment. Keep the current time or ask the examiner to add a sample opening.</p>'}</fieldset><p id="modal-error" class="error" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="close">Keep current time</button><button class="btn primary" type="submit" ${slots.length?'':'disabled'}>Send demo proposal</button></div></form>`);
}
function finishReschedule(id,proposalId,decision){resolveReschedule(state,{requestId:id,proposalId,actorRole:role,actorId:role==='student'?studentId:examinerId,decision});activity(state,state.requests.find(r=>r.id===id),'Demo schedule proposal '+decision+'.');save();modal.close();render();toast(decision==='accepted'?'New time confirmed in this browser only. No notification sent.':'Proposal closed. Your original appointment is unchanged.');}

// Workspace sections are split into tabs so the page stays short on phones.
let workspaceTab='overview';
function workspaceTabs(r){
 const remaining=r.checklist.filter(c=>!c.done).length,open=openClarifications(r).length;
 const tabs=[['overview','Overview',''],['prepare','Prepare',r.status==='accepted'&&remaining?remaining:''],['messages','Messages',open||''],['details','Details','']];
 return `<div class="workspace-tabs" role="tablist" aria-label="Checkride workspace sections">${tabs.map(([id,label,badge])=>`<button type="button" role="tab" id="tab-${id}" class="workspace-tab" data-action="workspace-tab" data-id="${id}" aria-selected="${workspaceTab===id}" aria-controls="workspace-panel" tabindex="${workspaceTab===id?0:-1}">${label}${badge!==''?`<span class="tab-badge" aria-label="${badge} open">${badge}</span>`:''}</button>`).join('')}</div>`;
}
function workspacePage(){
 const r=state.requests.find(x=>x.id===workspaceId);
 if(!r||!requestsForRole().some(x=>x.id===r.id))return intro('CHECKRIDE WORKSPACE','Choose a checkride.','Open a request from your checkride list.')+'<button class="btn primary" data-page="requests">View requests</button>';
 const e=eBy(r.examinerId),student=sBy(r.studentId),confirmed=r.status==='accepted',conversationShared=role!=='school'||canSchool(state,r.studentId,'conversation'),messages=conversationShared?(r.messages||[]):[],done=r.checklist.filter(c=>c.done).length;
 const canWrite=['pending','accepted'].includes(r.status)&&(role==='student'||role==='examiner');
 return `<button class="text-button workspace-back" data-page="requests">← Back to requests</button>`+intro('YOUR SHARED CHECKRIDE WORKSPACE',confirmed?'Everything for test day.':'Your request details.','One place for the plan, preparation, and demo conversation.',status(r))+`
 ${workspaceTabs(r)}<div class="workspace-tabpanel" role="tabpanel" id="workspace-panel" aria-labelledby="tab-${workspaceTab}">${
 workspaceTab==='prepare'?`<section class="panel"><div class="panel-head"><h2>Preparation checklist</h2><small class="location">${done} / ${r.checklist.length} complete</small></div>${confirmed?`<p class="location">Revision ${r.checklistRevision||0}${r.checklistRevision>r.checklistSeenRevision?' · Updated requirements — review before test day':''}</p>${role==='student'&&r.checklistRevision>r.checklistSeenRevision?`<button class="btn" data-action="prep-seen" data-id="${r.id}">Mark revision reviewed</button>`:''}<p class="subtitle">Curated by ${esc(e.name)}. Confirm required documents and equipment directly with your examiner.</p><ul class="checklist">${preparationItems(r)}</ul>${!r.checklist.length?'<p class="empty">Your examiner has not added checklist items yet.</p>':''}${role==='examiner'?`<button class="btn" data-action="checklist" data-id="${r.id}">Curate checklist →</button>`:''}${role==='school'?'<p class="location">School preview is read-only. Switch to the student to update completion.</p>':''}`:`<p class="subtitle">${r.status==='pending'?'The examiner can create your checklist after accepting this request.':'This arrangement is closed. Checklist changes are unavailable.'}</p>`}</section>`+(confirmed&&(role==='examiner'||templateUpdateAvailable(state,r))?templateWorkspacePanel(state,r,role):'')
 :workspaceTab==='messages'?`<section class="panel conversation-panel"><div class="panel-head"><h2>Demo conversation</h2></div><p class="location">Messages stay in this browser and aren’t sent anywhere.</p>${conversationShared?clarificationPanel(r):''}<div class="message-list" aria-label="Demo conversation history">${messages.length?messages.map(m=>`<article class="message ${m.actorRole===role?'own':''}"><div class="message-meta"><strong>${esc(m.actorRole==='student'?student.name:e.name)}</strong><span>${m.actorRole==='student'?'Student':'Examiner'}</span></div><p class="location">${esc(messageThreadLabel(r,m))}</p><p>${esc(m.text)}</p><time>${new Date(m.createdAt).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York'})} Eastern</time></article>`).join(''):`<div class="empty conversation-empty"><strong>${!conversationShared?'Conversation is private':confirmed?'Start the conversation':r.status==='pending'?'Clarify details before acceptance':'No conversation messages'}</strong>${!conversationShared?'The student has not granted this school conversation access. Scheduling and preparation remain visible under the overview grant.':confirmed?'Try a preparation question, then switch roles to reply.':r.status==='pending'?'Ask about aircraft, location, fees, or unknown terms. This is not a confirmed appointment.':'This arrangement is closed.'}</div>`}</div>${canWrite?`<form id="message-form" data-id="${r.id}" data-client="${crypto.randomUUID()}"><div class="field"><label for="message-text">Write as ${role==='student'?'student':'examiner'} · ${esc(role==='student'?student.name:e.name)}</label><textarea id="message-text" required maxlength="1000" placeholder="e.g. Which navigation logs should I prepare? (demo)"></textarea></div>${clarificationComposer(r)}<div class="form-actions"><button class="btn primary" type="submit">Add demo message</button></div></form>`:`<p class="notice">${role==='school'?conversationShared?'The student explicitly shared this demo conversation. School access is read-only.':'Conversation sharing is off. Overview and coordination grants do not include private message text.':r.status==='pending'?'Only the assigned student and examiner may clarify details.':'This arrangement is closed. Conversation history is read-only.'}</p>`}</section>`
 :workspaceTab==='details'?(confirmed?agreementPanel(r):'')+lifecyclePanel(r)+(confirmed?'':'<section class="panel"><p class="subtitle">More details appear here once the examiner accepts.</p></section>')
 :requestNextStepMarkup(r,true)+pendingOfferPanel(r)+(confirmed?'':agreementPanel(r))+`<section class="panel"><div class="panel-head"><h2>Appointment overview</h2><span class="demo-chip">Fictional demo</span></div><dl class="appointment-grid"><div><dt>Student</dt><dd>${esc(student.name)}</dd></div><div><dt>Examiner</dt><dd>${esc(e.name)}</dd></div><div><dt>Certificate or rating</dt><dd>${esc(r.certificate)}</dd></div><div><dt>Aircraft make and model</dt><dd>${esc(r.aircraft||'Not specified')}</dd></div><div><dt>${confirmed?'Confirmed date':'Requested date'}</dt><dd>${longDate(r.date)} · ${time(r.time)} Eastern</dd></div><div><dt>Operating airport</dt><dd>${esc(r.airport)} · ${esc(airportNames[r.airport]||'')}</dd></div><div><dt>${confirmed?'Agreed sample initial fee':'Quoted sample initial fee'}</dt><dd>${money(r.fee)} USD</dd></div><div><dt>Self-reported readiness</dt><dd>${esc(r.readiness||'Not provided')}</dd></div></dl><div class="request-note"><h3>Notes for the examiner</h3><p>${esc(r.notes||'No notes provided.')}</p></div>${role==='examiner'&&r.status==='pending'?`<div class="actions"><button class="btn primary" data-action="review" data-id="${r.id}">Review & accept</button><button class="btn" data-action="decline" data-id="${r.id}">Decline</button></div>`:''}${((role==='student'&&['pending','accepted'].includes(r.status))||(role==='examiner'&&r.status==='accepted'))?`<div class="actions"><button class="btn danger" data-action="cancel" data-id="${r.id}">${confirmed?'Cancel checkride':'Withdraw request'}</button></div>`:''}</section>`+schedulePanel(r)+dayPanel(state,r,{role,id:role==='school'?'piedmont':actor().id})
 }</div>`;
}
let modalOpener=null,submittedForm=null,conflict=false;
function restoreFocus(key){
 const scope=modal.open?modal:document;
 const target=key&&[...scope.querySelectorAll('button,input,select,textarea,a,[tabindex]')].find(el=>focusKey(el)===key&&canRestoreFocus(el));
 if(target)target.focus({preventScroll:true});
 else if(!modal.open)app.querySelector('h1')?.focus({preventScroll:true});
}
function readRevision(){try{return localStorage.getItem(STORAGE)}catch{return baseline}}
function showConflict(){
 conflict=true;
 for(const root of [app.parentElement,...(modal.open?[$('#modal-body')]:[])]){
  if(root.querySelector(':scope > .sync-conflict'))continue;
  const banner=document.createElement('section');banner.className='sync-conflict';banner.setAttribute('role','alert');
  banner.innerHTML='<strong>This demo changed in another tab.</strong><p>Your current entries are still here. Copy any text you want to keep. Saving and navigation are paused to avoid replacing newer browser-local changes.</p><button type="button" class="btn" data-action="refresh-local">Load latest demo</button>';
  root.prepend(banner);
 }
}
function guardRevision(){if(revisionChanged(baseline,readRevision()))showConflict();return !conflict}
function reloadLatest(){
 if(!window.confirm('Load the latest browser-local demo? This discards unsaved entries on this screen. Copy any text you need before continuing.'))return;
 const latest=readRevision();try{state=migratePilot(migrateWorkflows(migrateState(JSON.parse(latest))));baseline=latest;persistedDraftReceipts=state.draftReceipts||{};draftStore.clearStagedSubmissions();conflict=false;document.querySelectorAll('.sync-conflict').forEach(el=>el.remove());modal.close();examinerId=state.examiners.some(e=>e.id===examinerId)?examinerId:state.examiners[0].id;studentId=state.students.some(s=>s.id===studentId)?studentId:state.students[0].id;render({navigation:true});toast('Latest browser-local demo loaded. No messages were sent.')}catch{toast('Could not load the other tab’s data. Your entries have been kept.')}
}
document.addEventListener('click',ev=>{
 const button=ev.target.closest('button,a');if(!button)return;
 if(button.dataset.action==='refresh-local'){ev.preventDefault();ev.stopImmediatePropagation();reloadLatest();return}
 if(button.dataset.action==='close'){if(!allowDiscard(modal)){ev.preventDefault();ev.stopImmediatePropagation();}return;}
 if((button.dataset.page||['workspace','next-step','school-find'].includes(button.dataset.action)||button.matches('a'))&&!allowDiscard(document)){ev.preventDefault();ev.stopImmediatePropagation();return;}
 if(['add-item','remove-item'].includes(button.dataset.action)){const form=button.closest('form');if(form)form.dataset.dirty='true';}
 if(!guardRevision()){ev.preventDefault();ev.stopImmediatePropagation();}
},true);
document.addEventListener('submit',ev=>{if(!guardRevision()){ev.preventDefault();ev.stopImmediatePropagation();}},true);
document.addEventListener('change',ev=>{
 if(!['role','active-person'].includes(ev.target.id)&&!ev.target.dataset.checkRequest)return;
 if(!guardRevision()||(['role','active-person'].includes(ev.target.id)&&!allowDiscard(document))){
  if(ev.target.dataset.checkRequest)ev.target.checked=!ev.target.checked;
  if(ev.target.id==='role')ev.target.value=role;
  if(ev.target.id==='active-person')ev.target.value=role==='examiner'?examinerId:studentId;
  ev.stopImmediatePropagation();
 }
},true);
function hasDirtyForms(root){return [...root.querySelectorAll('form')].some(form=>isActiveDraftForm(form)&&(form.dataset.dirty==='true'||[...form.querySelectorAll('input,textarea,select')].some(el=>el.tagName==='SELECT'?[...el.options].some(option=>option.selected!==option.defaultSelected)&&el.value!==(el.querySelector('option[selected]')||el.options[0])?.value:['radio','checkbox'].includes(el.type)?el.checked!==el.defaultChecked:el.value!==el.defaultValue)))}
function allowDiscard(root){persistDrafts(root);return !hasDirtyForms(root)||(!draftsFailed()&&[...root.querySelectorAll('form')].filter(f=>isActiveDraftForm(f)&&hasDirtyForms(f.parentElement)).every(f=>draftKey(f)))||window.confirm('Discard entries that could not be saved and leave? Cancel keeps this screen open.')}
modal.addEventListener('cancel',ev=>{if(!allowDiscard(modal))ev.preventDefault()});
window.addEventListener('beforeunload',ev=>{if(hasDirtyForms(document)){ev.preventDefault();ev.returnValue=''}});
modal.addEventListener('close',()=>{if(!modal.open){restoreFocus(modalOpener||focusKey(document.activeElement));modalOpener=null;$('#modal-body').replaceChildren();}});
document.addEventListener('click',ev=>{const b=ev.target.closest('button,[data-page]');if(!b)return;if(b.dataset.page){page=b.dataset.page;render({navigation:true});return}const {action,id}=b.dataset;if(!action)return;try{switch(action){case'retry-save':persistDrafts(document);save();draftStore.retry();if(draftResetFailed)clearAllDrafts();render();persistenceStatus();toast('Browser save retried.');break;case'reconfirm':reconfirmAvailability(state,examinerId,actor());save();render();break;case'discard-draft':discardDraft(b.closest('form'));render();break;case'acknowledge':acknowledgeAgreement(state,id,actor());save();render();break;case'prep-seen':{const r=state.requests.find(x=>x.id===id);assertRequestActor(r,actor());if(role!=='student')throw Error('Only the student reviews preparation changes.');r.checklistSeenRevision=r.checklistRevision;save();render();break}case'calendar-view':calendarState(eBy(examinerId)).view=id;render();break;case'calendar-prev':case'calendar-next':{const c=calendarState(eBy(examinerId));c.month=shiftMonth(c.month,action==='calendar-prev'?-1:1);c.selected=c.month+'-01';render();break}case'calendar-day':calendarState(eBy(examinerId)).selected=id;render();break;case'school-filter':schoolFilters={query:'',view:id};submittedForm='school-filters';render();$('#school-view')?.focus();break;case'school-reset':schoolFilters={query:'',view:'all'};submittedForm='school-filters';render();$('#school-query')?.focus();break;case'close':modal.close();break;case'offer-opening':pendingOfferModal(id);break;case'pending-offer-accepted':case'pending-offer-declined':case'pending-offer-withdrawn':resolvePendingOffer(state,{requestId:id,offerId:b.dataset.offer,actorRole:role,actorId:actor().id,decision:action.replace('pending-offer-','')});activity(state,state.requests.find(r=>r.id===id),'Alternate-opening offer '+action.replace('pending-offer-','')+'; no booking or message sent.');save();render();toast('Offer updated locally. The request is still pending until examiner acceptance.');break;case'workspace-tab':workspaceTab=id;render();$('#tab-'+id)?.focus();break;case'next-step':workspaceId=id;page='workspace';workspaceTab=b.dataset.focus==='conversation'?'messages':b.dataset.focus==='prepare'?'prepare':'overview';render({navigation:true});if(b.dataset.focus==='conversation'){const intent=$('#message-intent');if(intent&&b.dataset.question&&!$('#message-text')?.value&&[...intent.options].some(o=>o.value==='reply:'+b.dataset.question))intent.value='reply:'+b.dataset.question;$('#message-text')?.focus();}break;case'workspace':workspaceId=id;page='workspace';workspaceTab='overview';render({navigation:true});break;case'view-examiner':examinerModal(id);break;case'clear-filters':filters=emptyFilters();moreFiltersOpen=false;submittedForm='filters';render();$('#query-filter')?.focus();toast('Filters reset. Showing all sample examiners.');break;case'school-find':studentId=id;filters={...emptyFilters(),certificate:sBy(id).certificate,airport:sBy(id).airport};page='find';render({navigation:true});break;case'review':reviewAcceptance(id);break;case'accept-confirm':decideAs(state,id,'accepted',actor(),$('#accept-ack')?.checked===true);save();modal.close();render();toast('Checkride confirmed in the demo. You can now curate the checklist.');break;case'decline':confirmModal('Decline this request?','Declines only this pending request. Other requests and confirmed appointments are unchanged.','decline-confirm',id,'Decline request');break;case'decline-confirm':decideAs(state,id,'declined',actor());save();modal.close();render();toast('Request declined.');break;case'cancel':{const pending=state.requests.find(r=>r.id===id)?.status==='pending';confirmModal(pending?'Withdraw this request?':'Cancel this arrangement?',pending?'Withdraws only this pending request. It was not a reservation; other requests and confirmed appointments are unchanged.':'This updates the demo only. A confirmed opening becomes available again. In a live service, agreed cancellation terms would apply.','cancel-confirm',id,pending?'Withdraw request':'Confirm cancellation');break}case'cancel-confirm':cancelAs(state,id,actor());save();modal.close();render();toast('Cancelled in the demo.');break;case'reschedule':rescheduleModal(id);break;case'reschedule-review':{const r=state.requests.find(x=>x.id===id),p=r?.rescheduleProposal;if(!p||p.id!==b.dataset.proposal)throw Error('This proposal has already changed.');confirmModal('Accept this schedule change?',`<strong>Currently confirmed:</strong> ${appointmentText(r)}<br><br><strong>Proposed replacement:</strong> ${appointmentText(p.to)}<br><br>Accepting replaces the original appointment and frees its opening. Saved sample fee: ${money(r.fee)}. No notifications are sent.`, 'reschedule-accepted',id,'Accept new time');$('#modal-body [data-action="reschedule-accepted"]').dataset.proposal=p.id;break}case'reschedule-accepted':case'reschedule-declined':case'reschedule-withdrawn':finishReschedule(id,b.dataset.proposal,action.replace('reschedule-',''));break;case'checklist':checklistModal(id);break;case'add-item':{const row=document.createElement('div');row.className='check-edit';row.innerHTML='<input aria-label="New checklist item" maxlength="250" required placeholder="e.g. Bring view-limiting device, if requested"><select aria-label="Preparation group"><option value="before">Before the test</option><option value="bring">Bring with you</option></select><button type="button" data-action="remove-item" aria-label="Remove checklist item">×</button>';$('#checklist-editor').append(row);row.querySelector('input').focus();break}case'remove-item':b.closest('.check-edit').remove();break;case'add-slot':slotModal();break;case'remove-slot':if(role!=='examiner')throw Error('Only the examiner may remove openings.');removeSlot(state,examinerId,id);save();render();toast('Opening removed.');break;case'reset-confirm':calendars.clear();state=migratePilot(migrateWorkflows(seed()));clearAllDrafts();save();role='student';page='find';studentId='maya';examinerId='elena';filters=emptyFilters();schoolFilters={query:'',view:'all'};modal.close();render({navigation:true});toast('Demo reset. Your sample workspace is ready.');break}}catch(error){modalError(error)}});
document.addEventListener('submit',ev=>{const f=ev.target;ev.preventDefault();try{if(draftKey(f)&&draftStore.isSubmitted(draftKey(f),draftFields(f)))throw Error('Already added in this session. Retry saving before submitting again.');if(f.id==='school-filters'){schoolFilters={query:$('#school-query').value.trim(),view:$('#school-view').value};submittedForm=f.id;render();toast($('#school-results').textContent)}if(f.id==='filters'){const next={query:$('#query-filter').value.trim(),certificate:$('#certificate-filter').value,airport:$('#airport-filter').value,start:$('#start-filter').value,end:$('#end-filter').value,maxFee:$('#fee-filter').value,sort:$('#sort-filter').value};try{validateFilters(next)}catch(error){$('#filter-error').textContent=error.message;return}filters=next;submittedForm='filters';render();toast($('#discovery-results').textContent)}if(f.id==='request-form'){if(!prepareRequestReview(f))return;const requestedStudent=$('#request-student')?.value||studentId;if(role==='examiner'||(role==='school'&&!canSchool(state,requestedStudent,'coordinate')))throw Error('This preview has no grant to submit for this student.');const slot=f.querySelector('input[name="slot"]:checked');if(!slot)throw Error('Choose an opening.');const newRequest=requestSlot(state,{studentId:requestedStudent,examinerId:f.dataset.examiner,slotId:slot.value,certificate:$('#request-certificate').value,source:role==='school'?'Flight school':'Student',aircraft:$('#request-aircraft').value,readiness:$('#request-readiness').value,notes:$('#request-notes').value});snapshotAgreement(state,newRequest,role==='student');activity(state,newRequest,'Demo request created; waiting on examiner review.');completeDraftSubmission(f);modal.close();page='requests';render({navigation:true});toast('Request sent in demo. Awaiting examiner acceptance.')}if(f.id==='pending-offer-form'){proposePendingOffer(state,{requestId:f.dataset.id,actorRole:role,actorId:actor().id,slotId:$('#pending-offer-slot').value,clientId:f.dataset.client});activity(state,state.requests.find(r=>r.id===f.dataset.id),'Examiner offered an alternate opening; waiting on student consent.');save();modal.close();render();toast('Alternate opening offered locally. Original request is unchanged and not reserved.')}if(f.id==='reschedule-form'){const slot=f.querySelector('input[name="reschedule-slot"]:checked');if(!slot)throw Error('Choose an available opening.');proposeReschedule(state,{requestId:f.dataset.id,actorRole:role,actorId:role==='student'?studentId:examinerId,slotId:slot.value,clientId:f.dataset.client});activity(state,state.requests.find(r=>r.id===f.dataset.id),'New demo schedule proposal; original appointment stays confirmed.');save();modal.close();render();toast('Proposal saved locally. The original time remains confirmed.')}if(f.id==='message-form'){addMessage(state,{requestId:f.dataset.id,actorRole:role,actorId:role==='student'?studentId:examinerId,text:$('#message-text').value,clientId:f.dataset.client,replyRequested:$('#message-intent').value==='question',replyTo:$('#message-intent').value.startsWith('reply:')?$('#message-intent').value.slice(6):null});activity(state,state.requests.find(r=>r.id===f.dataset.id),'New demo conversation message. Nothing sent externally.');completeDraftSubmission(f);submittedForm=f.id;render();$('#message-text')?.focus();toast('Saved to this demo only. No message was sent.')}if(f.id==='fees'){if(role!=='examiner')throw Error('Only the examiner may edit their profile.');const e=eBy(examinerId);e.fee=Number($('#initial-fee').value);e.retestFee=Number($('#retest-fee').value);e.notice=$('#preferences').value.trim();e.profileUpdatedAt=new Date().toISOString();e.terms=Object.fromEntries(termKeys.map(k=>[k,$('#term-'+k).value.trim()]));completeDraftSubmission(f);submittedForm=f.id;render();toast('Published fees and preferences updated.')}if(f.id==='slot-form'){if(role!=='examiner')throw Error('Only the examiner may add openings.');addSlot(state,examinerId,{date:$('#slot-date').value,time:$('#slot-time').value,airport:$('#slot-airport').value});save();modal.close();render();toast('Sample opening published.')}if(f.id==='checklist-form'){const r=state.requests.find(r=>r.id===f.dataset.id);if(!r||r.status!=='accepted'||role!=='examiner'||r.examinerId!==examinerId)throw Error('This checklist is no longer editable.');r.checklist=[...f.querySelectorAll('.check-edit input')].map((el,i)=>{const prev=r.checklist.find(c=>c.id===el.dataset.item);return{id:prev?.id||crypto.randomUUID(),text:el.value.trim(),group:el.closest('.check-edit').querySelector('select').value,done:prev?.text===el.value.trim()?prev.done:false}});r.checklistRevision=(r.checklistRevision||0)+1;activity(state,r,'Examiner updated preparation requirements.');save();modal.close();render();toast('Checklist saved. Switch to the student to see it.')}}catch(error){modalError(error)}});
document.addEventListener('change',ev=>{if(ev.target.id==='role'){role=ev.target.value;page='dashboard';render({navigation:true})}if(ev.target.id==='active-person'){if(role==='examiner')examinerId=ev.target.value;else studentId=ev.target.value;render({navigation:true})}if(ev.target.dataset.checkRequest){const r=state.requests.find(r=>r.id===ev.target.dataset.checkRequest),c=r?.checklist.find(c=>c.id===ev.target.dataset.checkItem);if(!c||r.status!=='accepted'||(role!=='student'||r.studentId!==studentId))return toast('This checklist is no longer editable.');c.done=ev.target.checked;save();ev.target.closest('label').classList.toggle('done',c.done);render()}});
const resetDemo=()=>confirmModal('Start fresh?','This removes only your browser-local demo changes and restores the fictional sample workspace.','reset-confirm','','Reset demo');$('#reset').addEventListener('click',resetDemo);$('#reset-footer').addEventListener('click',resetDemo);
$('.brand').addEventListener('click',ev=>{ev.preventDefault();page='dashboard';render({navigation:true})});modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if((ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)&&allowDiscard(modal))modal.close()}});
window.addEventListener('storage',ev=>{if((ev.key===STORAGE||ev.key===null)&&revisionChanged(baseline,readRevision()))showConflict()});

document.addEventListener('toggle',ev=>{if(ev.target.id==='more-filters')moreFiltersOpen=ev.target.open;},true);

function dashboardPage(){
 const items=actionItems(state,role,role==='examiner'?examinerId:studentId),rs=requestsForRole(),ids=new Set(rs.map(r=>r.id));
 const events=(state.activity||[]).filter(a=>ids.has(a.requestId)).slice(-8).reverse();
 return intro('CLEAR SKIES · YOUR NEXT STEP','Action needed.','See who is waiting, what needs attention, and where to go next.',role==='school'?'':roleSelector(role))+
 ` <div class="stats"><div class="stat"><label>${role==='school'?'SHARED NEXT STEPS':'YOUR NEXT ACTIONS'}</label><b>${items.filter(i=>role==='school'?i.kind!=='info':i.disposition==='action').length}</b><small>${items.filter(i=>i.disposition==='waiting').length} waiting on assigned participants</small></div><div class="stat"><label>PENDING REQUESTS</label><b>${rs.filter(r=>r.status==='pending').length}</b><small>Awaiting examiner</small></div><div class="stat"><label>CONFIRMED REQUESTS</label><b>${rs.filter(r=>r.status==='accepted').length}</b><small>Accepted by examiner</small></div></div>
 ${role==='examiner'?`<section class="panel"><h2>Availability check</h2><p>${esc(availabilityFreshness(eBy(examinerId)).label)}</p><button class="btn" data-page="availability">Review openings & reconfirm →</button></section>`:''}
 <section class="panel"><div class="panel-head"><h2>Your coordination queue</h2><button class="btn" data-page="${role==='school'?'school':role==='examiner'?'requests':'find'}">${role==='school'?'Student overview':role==='examiner'?'Review requests':'Find an examiner'} →</button></div>
 ${['action','waiting','info'].map(group=>{const rows=items.filter(i=>i.disposition===group);return rows.length?`<h3>${group==='action'?'Your next actions':group==='waiting'?'Waiting on assigned participants':'Up to date & request history'}</h3>${rows.map(item=>actionRow(item)).join('')}`:''}).join('')||'<p class="empty">No requests in this preview. Browse openings or review student permissions.</p>'}</section>
 ${role==='student'?schoolGrantPanel():role==='school'?'<section class="panel"><h2>Student permission comes first</h2><p>Students choose what the school can see. Switch to a student’s Action needed page to share access.</p></section>':''}
 <section class="panel"><h2>Demo activity</h2>${events.length?events.map(a=>`<p><b>${esc(a.text)}</b><br><small>${esc(new Date(a.at).toLocaleString())}</small></p>`).join(''):'<p>No activity in this preview yet.</p>'}</section>`;
}
function pendingOfferPanel(r){const offer=r.pendingOffer,availability=pendingRequestAvailability(state,r),offered=offer?pendingOfferAvailability(state,r):null;if(r.status!=='pending')return r.pendingOfferHistory?.length?`<section class="panel"><h2>Alternate-opening history</h2>${r.pendingOfferHistory.map(o=>`<p>${appointmentText(o.to)} · ${esc(o.status==='pending'?'Inactive — request closed':o.status)}</p>`).join('')}</section>`:'';if(availability.available&&!offer&&!r.pendingOfferHistory?.length)return '';return `<section class="panel"><h2>Alternate openings</h2>${availability.available?'':`<p class="notice">${esc(availability.reason)}</p>`}${offer?`<h3>Alternate opening offered</h3>${!offered.available?`<p class="error">${esc(offered.reason)} The examiner can withdraw this offer and propose another; the student can decline it.</p>`:''}<p>Original request: ${appointmentText(r)}<br>Proposed opening: ${appointmentText(offer.to)}</p><p class="location">If the student agrees, the request moves to this time and still needs the examiner’s acceptance.</p><details><summary>Review proposed details & saved terms</summary>${agreementMarkup(offer.agreement.details)}</details>${role==='student'?`<div class="actions"><button class="btn primary" data-action="pending-offer-accepted" data-id="${r.id}" data-offer="${esc(offer.id)}" ${offered.available?'':'disabled'}>Use this opening · still pending</button><button class="btn" data-action="pending-offer-declined" data-id="${r.id}" data-offer="${esc(offer.id)}">Decline alternate</button></div>`:role==='examiner'?`<p>Waiting on ${esc(sBy(r.studentId).name)} to review this specific opening.</p><button class="btn" data-action="pending-offer-withdrawn" data-id="${r.id}" data-offer="${esc(offer.id)}">Withdraw alternate offer</button>`:'<p class="location">Only the assigned student can accept this alternate; school preview is read-only.</p>'}`:role==='examiner'&&!availability.available?`<button class="btn" data-action="offer-opening" data-id="${r.id}">Offer another opening</button>`:''}${r.pendingOfferHistory?.length?`<details><summary>Alternate-opening history (${r.pendingOfferHistory.length})</summary>${r.pendingOfferHistory.map(o=>`<p>${appointmentText(o.to)} · ${esc(o.status)}</p>`).join('')}</details>`:''}</section>`;}
function pendingOfferModal(id){const r=state.requests.find(r=>r.id===id);if(!r||r.status!=='pending'||role!=='examiner'||r.examinerId!==examinerId)throw Error('Only the assigned examiner can offer another opening on a pending request.');const openings=pendingOfferOpenings(state,r);openModal(modalHead('Offer an alternate opening')+`<p class="location">The student chooses whether to switch. You still accept the request afterward.</p><form id="pending-offer-form" data-id="${r.id}" data-client="${crypto.randomUUID()}"><div class="field"><label for="pending-offer-slot">Available alternate opening · Eastern</label><select id="pending-offer-slot" required>${openings.map(slot=>`<option value="${esc(slot.id)}">${esc(slot.date+' · '+slot.time+' · '+slot.airport)}</option>`).join('')}</select></div>${openings.length?'':'<p class="notice">No other available openings. Add an opening or decline the request.</p>'}<div id="modal-error" class="error" role="alert"></div><div class="actions"><button class="btn" type="button" data-action="close">Keep current request</button><button class="btn primary" type="submit" ${openings.length?'':'disabled'}>Offer opening to student</button></div></form>`);}
function clarificationPanel(r){const threads=clarificationThreads(r);return `<section class="clarification-threads" aria-label="Clarification questions"><h3>Clarification questions</h3><p class="location">${threads.filter(t=>t.status==='open').length} open · ${threads.filter(t=>t.status==='answered').length} answered</p>${threads.map((t,i)=>`<article class="request-note"><h3>Q${i+1} · ${t.status==='open'?'Open — reply requested':'Answered'}</h3><p>${esc(t.question.text)}</p><small>${esc(ownerLabel(r,t.question.actorRole))}${t.legacy?' · Legacy reply request: no answer inferred from old messages':''}</small>${t.reply?`<p><b>Answer:</b> ${esc(t.reply.text)}</p>`:`<p class="location">${['pending','accepted'].includes(r.status)?'Next owner: '+esc(ownerLabel(r,t.question.actorRole==='student'?'examiner':'student')):'Request closed; question retained for reference.'}</p>`}</article>`).join('')||'<p>No clarification questions yet.</p>'}</section>`;}
function messageThreadLabel(r,m){const threads=clarificationThreads(r),question=threads.findIndex(t=>t.id===m.id),answer=threads.findIndex(t=>t.reply?.id===m.id);return question>=0?'Question Q'+(question+1):answer>=0?'Answer to Q'+(answer+1):'Informational note';}
function clarificationComposer(r){const threads=clarificationThreads(r),open=openClarifications(r).filter(t=>t.question.actorRole!==role);return `<div class="field"><label for="message-intent">Message purpose</label><select id="message-intent"><option value="note">Note</option><option value="question">Ask a question</option>${open.map(t=>`<option value="reply:${esc(t.id)}">Answer Q${threads.findIndex(x=>x.id===t.id)+1}: ${esc(t.question.text.slice(0,80))}</option>`).join('')}</select></div>`;}
function ownerLabel(r,owner){return owner==='student'?sBy(r.studentId).name+' · Student':owner==='examiner'?eBy(r.examinerId).name+' · Examiner':'No response required';}
function actionRow(item){const r=state.requests.find(r=>r.id===item.requestId);return `<article class="action-row"><div><span class="demo-chip">${item.disposition==='action'?'Your next action':item.disposition==='waiting'?'Waiting':'For reference'}</span><h3>${esc(item.title)}</h3><p>${esc(sBy(r.studentId).name)} · ${esc(eBy(r.examinerId).name)} · ${date(r.date)}</p><p>Next owner: ${esc(ownerLabel(r,item.owner))}</p></div><div class="actions"><button class="btn" data-action="next-step" data-id="${esc(r.id)}" data-question="${esc(item.questionId||'')}" data-focus="${item.title.startsWith('Reply to')&&item.owner===role?'conversation':/preparation/i.test(item.title)?'prepare':'details'}">${item.title.startsWith('Reply to')&&item.owner===role?'Write clarification reply':'Open next step'} →</button>${role==='student'&&r.status==='pending'?`<button class="btn" data-action="cancel" data-id="${esc(r.id)}">Withdraw this request</button>`:''}</div></article>`;}
function requestNextStepMarkup(r,panel=false){const items=actionItems(state,role,role==='examiner'?examinerId:studentId).filter(i=>i.requestId===r.id);return `<section class="${panel?'panel':'request-next-step'}" aria-label="Request next steps"><h3>Next step${items.length>1?'s':''}</h3>${items.map(i=>`<p>${esc(i.title)}<br><small>${esc(ownerLabel(r,i.owner))}${i.owner===role?' · Your action':i.owner?' · Waiting':''}</small></p>`).join('')}${r.source==='Flight school'||role==='school'?`<p class="location">${r.source==='Flight school'?'Submitted by the school. ':''}${role==='school'?'School view is read-only.':''}</p>`:''}</section>`;}
function schoolGrantPanel(){
 const grant=state.schoolGrants.find(g=>g.studentId===studentId&&g.active),scope=grant?.scope||'none';
 return `<section class="panel"><h2>Your sample school access</h2><p>Piedmont Flight Academy · Choose what the school can see and do for ${esc(sBy(studentId).name)}.</p><form id="grant-form"><div class="field"><label for="grant-scope">Demo permission</label><select id="grant-scope">${[['none','No access / revoke'],['overview','Overview: scheduling and preparation progress'],['coordinate','Overview + submit requests on my behalf']].map(([v,t])=>`<option value="${v}" ${scope===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="acknowledgement"><input id="grant-conversation" type="checkbox" ${grant?.conversation===true?'checked':''}> Separately share my demo conversation text with this school (read-only)</label><button class="btn primary" type="submit">Save demo permission</button></form><p class="location">Schools can view but can’t accept, reschedule, or change preparation.</p></section>`;
}
function agreementMarkup(d){return `<dl class="appointment-grid"><div><dt>Test</dt><dd>${esc(d.certificate)}</dd></div><div><dt>Aircraft</dt><dd>${esc(d.aircraft)}</dd></div><div><dt>Airport</dt><dd>${esc(d.airport)}</dd></div><div><dt>Date & time</dt><dd>${esc(d.date)} · ${esc(d.time)} · ${esc(d.timeZone)}</dd></div><div><dt>Initial fee snapshot</dt><dd>${money(d.fee)} USD</dd></div>${termKeys.map(k=>`<div><dt>${k[0].toUpperCase()+k.slice(1)} / additional charges</dt><dd>${esc(d.terms?.[k]||'Not specified')}</dd></div>`).join('')}</dl><p class="location">Blank terms are unknown, not waived. Ask in the conversation if anything is unclear.</p>`}
function agreementPanel(r){const d=r.agreement?.details||reviewDetails(state,r);return `<section class="panel"><h2>Request review snapshot</h2>${agreementMarkup(d)}<p class="location">Student reviewed: ${r.agreement?.studentAcknowledgedAt?'Yes':'Not yet'} · Examiner reviewed: ${r.agreement?.examinerAcknowledgedAt?'Yes':'Not yet'}</p>${r.status==='pending'&&role==='student'&&!r.agreement?.studentAcknowledgedAt?`<button class="btn" data-action="acknowledge" data-id="${r.id}">I’ve reviewed these details</button>`:''}</section>`}
function reviewAcceptance(id){
 const r=state.requests.find(r=>r.id===id);assertRequestActor(r,actor());if(role!=='examiner'||r.status!=='pending')throw Error('Only the assigned examiner can review a pending request.');
 openModal(modalHead('Review before confirming')+(!pendingRequestAvailability(state,r).available?'<p class="error">This requested opening is unavailable. Offer another opening or decline; this request stays pending.</p>':'')+(r.pendingOffer?.status==='pending'?'<p class="error">Resolve or withdraw the alternate-opening offer before accepting.</p>':'')+(pendingClarification(r)?'<p class="notice">Some questions in the conversation are still open.</p>':'')+agreementMarkup(r.agreement?.details||reviewDetails(state,r))+`<p>Readiness: ${esc(r.readiness)}<br>Student notes: ${esc(r.notes||'None')}</p><p class="location">Accepting closes your day to other requests.</p>${!r.agreement?.studentAcknowledgedAt?'<p class="error">Student acknowledgement is still needed. Open the student preview to review this snapshot.</p>':''}<label class="acknowledgement"><input type="checkbox" id="accept-ack"> I’ve reviewed these details.</label><div id="modal-error" class="error" role="alert"></div><div class="actions"><button class="btn" data-action="clarify" data-id="${id}">Clarify in demo conversation</button><button class="btn primary" data-action="accept-confirm" data-id="${id}" ${!r.agreement?.studentAcknowledgedAt||!pendingRequestAvailability(state,r).available||r.pendingOffer?.status==='pending'?'disabled':''}>Accept demo request</button></div>`);
}
function prepareRequestReview(form){
 const slot=eBy(form.dataset.examiner)?.slots.find(s=>s.id===form.querySelector('input[name="slot"]:checked')?.value);if(!slot)throw Error('Choose an opening.');
 const d=reviewDetails(state,{id:'draft',...slot,examinerId:form.dataset.examiner,certificate:$('#request-certificate').value,aircraft:$('#request-aircraft').value,fee:eBy(form.dataset.examiner).fee});
 const fingerprint=JSON.stringify(d);let panel=form.querySelector('.request-review');
 if(panel&&form.dataset.review===fingerprint&&$('#request-ack')?.checked)return true;
 if(!panel){panel=document.createElement('section');panel.className='request-review';form.querySelector('.form-actions').before(panel);}
 panel.innerHTML='<h3>Review your request</h3>'+agreementMarkup(d)+'<label class="acknowledgement"><input id="request-ack" type="checkbox"> I’ve reviewed these details. I understand this is a request, not a booking.</label>';
 form.dataset.review=fingerprint;form.querySelector('[type="submit"]').textContent='Confirm demo request →';panel.scrollIntoView({block:'nearest'});$('#request-ack').focus();return false;
}
function preparationItems(r){return ['before','bring'].map(group=>`<li class="prep-group"><h3>${group==='before'?'Before the test':'Bring with you'}</h3><small>Examiner curates · Student marks complete</small><ul>${r.checklist.filter(c=>(c.group||'before')===group).map(c=>`<li><label class="${c.done?'done':''}"><input type="checkbox" data-check-request="${r.id}" data-check-item="${c.id}" ${c.done?'checked':''} ${role==='student'?'':'disabled'}>${esc(c.text)}</label></li>`).join('')||'<li>No items specified in this group.</li>'}</ul></li>`).join('')}
function lifecyclePanel(r){if(r.status!=='accepted')return '';return `<section class="panel"><h2>After the test · Coordination follow-up</h2><p class="location">For coordination only. This doesn’t record a pass or fail.</p><p>Current: <b>${esc(r.coordination||'scheduled')}</b></p>${role!=='school'?`<form id="lifecycle-form" data-id="${r.id}"><label for="lifecycle-state">Update coordination</label><select id="lifecycle-state">${[['scheduled','Scheduled / correction'],['completed','Completed — no result recorded'],['discontinued','Discontinued — follow-up needed'],['retest','Retest follow-up needed']].map(([v,l])=>`<option value="${v}" ${r.coordination===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn" type="submit">Record demo update</button></form>`:''}${r.coordination==='retest'||r.coordination==='discontinued'?'<p>Discuss the next step in the demo conversation. A fresh request needs a separate review and acceptance.</p>':''}<details><summary>Coordination history (${r.lifecycleHistory?.length||0})</summary>${(r.lifecycleHistory||[]).map(h=>`<p>${esc(h.value)} · reported by ${esc(h.actorRole)} · ${esc(new Date(h.at).toLocaleString())}</p>`).join('')}</details></section>`}

function applyRoute(){({role,page,studentId,examinerId,workspaceId}=parseRoute(location.search,state));}
function syncRoute(replace=false){const search=routeSearch({role,page,studentId,examinerId,workspaceId});if(location.search!==search)history[replace?'replaceState':'pushState'](null,'',location.pathname+search);}
window.addEventListener('popstate',()=>{if(!guardRevision()||!allowDiscard(document)){syncRoute();return}modal.close();applyRoute();render({navigation:true});});
const DRAFT_PREFIX='checkride-draft-v2:';
function draftKey(form){
 if(form.id==='request-form')return DRAFT_PREFIX+role+':'+(form.dataset.student||studentId)+':request:'+form.dataset.examiner;
 if(form.id==='message-form')return DRAFT_PREFIX+role+':'+(role==='student'?studentId:examinerId)+':message:'+form.dataset.id;
 if(form.id==='fees')return DRAFT_PREFIX+'examiner:'+examinerId+':fees';
 return null;
}
function draftFields(form){return [...form.querySelectorAll('input[id],select[id],textarea[id],input[name="slot"]')].filter(el=>!['request-ack','request-student'].includes(el.id)).map(el=>({id:el.id||'slot:'+el.value,value:el.value,checked:el.checked===true}));}
function persistDrafts(root){for(const f of root.querySelectorAll('form')){const key=draftKey(f);if(key&&isActiveDraftForm(f))draftStore.save(key,draftFields(f));}persistenceStatus();}
function restoreDurableDrafts(root){for(const f of root.querySelectorAll('form')){const key=draftKey(f);if(!key)continue;const fields=draftStore.read(key,persistedDraftReceipts[key]);for(const field of fields){const el=[...f.querySelectorAll('input,select,textarea')].find(el=>(el.id||'slot:'+el.value)===field.id);if(!el)continue;if(el.id==='message-intent'&&field.value.startsWith('reply:')&&![...el.options].some(o=>o.value===field.value)){const option=document.createElement('option');option.value=field.value;option.textContent='Saved question is no longer open — choose another purpose';el.append(option);}if(el.type==='radio')el.checked=field.checked;else if(el.type==='checkbox')el.checked=field.checked;else if(el.tagName!=='SELECT'||[...el.options].some(o=>o.value===field.value))el.value=field.value;}
 if(!f.querySelector('.draft-notice')){const p=document.createElement('p');p.className='draft-notice location';p.innerHTML='Fictional entries save as a draft in this browser. <button class="text-button" type="button" data-action="discard-draft">Discard saved draft</button>';f.append(p);}
}}
function completeDraftSubmission(f){draftStore.stageSubmission(draftKey(f),draftFields(f));save();}
function commitSavedDrafts(){for(const submitted of draftStore.commitSubmissions()){for(const f of document.querySelectorAll('form')){if(draftKey(f)===submitted.key&&JSON.stringify(draftFields(f))===JSON.stringify(submitted.fields)){f.reset();f.dataset.dirty='false';f.querySelector('.request-review')?.remove();delete f.dataset.review;submittedForm=f.id;}}}}
function discardDraft(f){if(!f)return;const key=draftKey(f);if(key)draftStore.discard(key);f.reset();f.dataset.dirty='false';f.querySelector('.request-review')?.remove();delete f.dataset.review;persistenceStatus();}
function clearAllDrafts(){draftStore.clearStagedSubmissions();let keys=draftStore.keys();try{keys=[...new Set([...keys,...Object.keys(localStorage).filter(k=>k.startsWith(DRAFT_PREFIX))])];draftResetFailed=false}catch{draftResetFailed=true}for(const key of keys)draftStore.discard(key);persistenceStatus();}
document.addEventListener('input',ev=>{const form=ev.target.closest('form');if(form&&draftKey(form)&&ev.target.id!=='request-student'){form.dataset.dirty='true';persistDrafts(form.parentElement);}});
document.addEventListener('change',ev=>{const f=ev.target.closest('form');if(f&&draftKey(f)){if(ev.target.id==='request-student'){const selected=ev.target.value;persistDrafts(f.parentElement);f.reset();f.querySelector('.request-review')?.remove();delete f.dataset.review;ev.target.value=studentId=selected;f.dataset.student=selected;restoreDurableDrafts(modal);}persistDrafts(f.parentElement);}});
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action="clarify"]');if(!b)return;modal.close();workspaceId=b.dataset.id;page='workspace';workspaceTab='messages';render({navigation:true});$('#message-text')?.focus();});
document.addEventListener('submit',ev=>{try{const f=ev.target;if(f.id==='grant-form'){setSchoolGrant(state,studentId,$('#grant-scope').value,actor(),$('#grant-conversation').checked);save();submittedForm=f.id;render();toast('Demo school scope updated.');}if(f.id==='lifecycle-form'){setLifecycle(state,f.dataset.id,$('#lifecycle-state').value,actor());save();submittedForm=f.id;render();toast('User-reported demo coordination updated.');}}catch(error){modalError(error)}});


document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b)return;try{switch(b.dataset.action){
 case 'edit-template':if(role!=='examiner')throw Error('Only an examiner can edit templates.');openModal(modalHead('Reusable template · '+esc(b.dataset.id))+templateEditor(state,examinerId,b.dataset.id));break;
 case 'apply-template':if(role!=='examiner')throw Error('Only the assigned examiner may copy a template.');confirmModal('Replace this student’s checklist?','Copy the latest reusable template into this accepted appointment. Personalized items not in the template will be removed. Unchanged items retain completion. Other student copies are untouched.','apply-template-confirm',b.dataset.id,'Copy template');break;
 case 'apply-template-confirm':{const r=state.requests.find(r=>r.id===b.dataset.id),t=r&&templateFor(state,r.examinerId,r.certificate);if(r?.templateSource?.version===t?.version)throw Error('This template version is already copied. Your personalized checklist is unchanged; use Curate checklist to edit it.');}applyTemplate(state,b.dataset.id,actor());save();modal.close();render();toast('Student template copy saved locally. Customize it with Curate checklist.');break;
 case 'template-seen':acknowledgeTemplateUpdate(state,b.dataset.id,actor());save();render();toast('Template change notice reviewed. Your personalized checklist is unchanged.');break;
}}catch(error){modalError(error)}});
document.addEventListener('submit',ev=>{const f=ev.target;try{
 if(f.id==='template-form'){const items=['before','bring'].flatMap(group=>$('#template-'+group).value.split('\n').map(text=>text.trim()).filter(Boolean).map(text=>({text,group})));saveTemplate(state,{examinerId,certificate:f.dataset.certificate,items,expectedVersion:Number(f.dataset.version)},actor());save();modal.close();render();toast('Template saved. Existing student copies are unchanged.');}
}catch(error){modalError(error)}});

applyRoute();render();syncRoute(true);

// Arrow keys move between workspace tabs.
document.addEventListener('keydown',ev=>{
 const tab=ev.target.closest?.('[role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;
 const tabs=[...tab.parentElement.querySelectorAll('[role="tab"]')],i=tabs.indexOf(tab);
 const next=ev.key==='Home'?tabs[0]:ev.key==='End'?tabs.at(-1):tabs[(i+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];
 ev.preventDefault();next.click();
});
